insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1b9394c8-71a4-4281-9046-5014c86b7514', 'fr', 'Tu engages la conversation. Elle répond chaleureusement, mais son amie l’attrape par le bras et l’emmène.', '["Politesse : elle était gentille avant que son amie interrompe", "Ouverture au départ, mais une interruption extérieure y a mis fin", "Froideur : elle s’est servie de son amie pour s’échapper"]'::jsonb, 'Sa réponse chaleureuse était un signal d’ouverture ; l’interruption de son amie vient de l’extérieur, ce n’est pas son signal à elle.')
