insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1ccbf131-6df9-4829-afc6-793d8a586ba6', 'fr', 'Elle te sourit. Tu commences à préparer ton accroche. Meilleure chose à faire ?', '["Répéter ce que tu vas dire, puis y aller", "Aller la voir tout de suite, même sans phrase peaufinée", "Attendre qu’elle te regarde à nouveau pour confirmer"]'::jsonb, 'Agir vite empêche le doute de s’installer. Bouge dans les trois secondes après l’avoir remarquée.')
