insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('243e45da-4e6e-4747-bd72-4c71c92d582b', 'fr', 'Tu la vois, mais tu es mal habillé. Que fais-tu ?', '["L’aborder quand même", "Laisser tomber, ton apparence va jouer contre toi", "Attendre d’être prêt", "Croiser son regard sans lui parler"]'::jsonb, 'Te limiter aux conditions parfaites tue la quantité d’approches. Tu peux aborder n’importe quand.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('24ae814b-7816-4ac9-af4c-f56e4e9d8de9', 'fr', 'Pourquoi les accroches indirectes paraissent-elles moins intrusives ?', '["Elles évitent le silence", "Elles montrent de l’assurance", "Elles s’inscrivent dans le moment que vous vivez déjà"]'::jsonb, 'Une situation partagée rend l’entrée en matière attendue et facile à suivre.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('24ebc378-571a-47ca-a34d-406494e05bf1', 'fr', 'Tu vois qu’elle dessine quelque chose dans un carnet. Quelle accroche montre de la curiosité ?', '["« Tu as l’air d’être une artiste. »", "« Je peux m’asseoir ici ? »", "« Tu es douée, ça se voit. »", "« Tu dessines quoi ? Ça a l’air plein de détails. »"]'::jsonb, 'Être curieux de ce qu’elle vit invite un vrai lien, sans arrière-pensée.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('26e9ec88-6ad1-419a-a087-c91efb8998d2', 'fr', 'Quelles habitudes t’aident à aborder régulièrement sur la durée ?', '["Parler aux gens tous les jours", "Attendre de te sentir prêt", "Aller vers les autres dans les lieux du quotidien"]'::jsonb, 'Aller régulièrement vers les autres réduit la pression et rend les échanges plus faciles.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2726ad43-344c-4ec6-a996-4df4d37978f4', 'fr', 'Tu vois une femme avec un accessoire original. Que pourrais-tu dire en premier pour éveiller sa curiosité ?', '["« Tu l’as trouvé où ? »", "« J’ai une petite question sur ce que tu portes là. »", "« C’est cool, j’aime bien. »", "« Tu es d’ici ? »"]'::jsonb, 'La mise en place crée de la curiosité avant de révéler la question.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('29a122e7-d801-4e7c-bf05-40a46aba0960', 'fr', 'Elle fait la queue seule. Tu veux lui demander son avis. Meilleure accroche ?', '["« Salut, ta journée se passe bien ? »", "« Petite question : plutôt café ou plutôt thé ? »", "« À ton avis, c’est quoi le mieux : leur boisson de saison ou la classique ? »"]'::jsonb, 'Un débat ou un dilemme sollicite son avis, ce qui la valorise et l’implique.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2ada2eb4-7e4e-4ea9-b9d1-7cde29ea6304', 'fr', 'Elle se tourne à peine et lâche un « salut » plat. Qu’est-ce que ça signale ?', '["De la timidité", "De la curiosité", "Un intérêt neutre", "Une réaction froide"]'::jsonb, 'Une implication minimale veut dire : retire-toi ; pars proprement.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2b69af0f-cead-4bcb-8f8d-580b110d13f2', 'fr', 'Quel signal montre le plus clairement un manque d’intérêt ?', '["Un bref sourire", "Elle répond à tes questions", "Elle se détourne", "Un rire poli"]'::jsonb, 'Un corps tourné ailleurs signale le désintérêt. Va-t’en.')
