insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2d63f1fb-98b5-4678-aec8-6b0c2abded25', 'fr', 'Elle se tourne vers toi, sourit chaleureusement, répond en détail, mais n’arrête pas de regarder vers ses amies.', '["Ouverture : ses réponses montrent qu’elle est impliquée malgré ses amies", "Politesse : elle est aimable, mais ses regards répétés montrent une attention partagée", "Neutre : elle garde juste un œil sur ses amies ; continue normalement"]'::jsonb, 'Ses réponses montrent un échange poli, mais son attention n’est pas entièrement là.')
