insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2f7b8ecd-021a-40d3-aea3-50d2530f7f6e', 'fr', 'Elle répond chaleureusement, mais continue de faire défiler son téléphone. Que dois-tu en conclure ?', '["Elle est timide", "Elle est ouverte à l’échange", "Elle est distraite, mais intéressée", "Elle est polie"]'::jsonb, 'Une attention partagée veut généralement dire politesse, pas implication.')
