insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4232f870-74a7-4557-9e29-70a586b48204', 'fr', 'Tu la vois dans un bar. Quelle est l’approche directe ?', '["Faire une remarque sur la musique ou les boissons pour lancer la conversation", "Croiser son regard et sourire", "« Tu as attiré mon regard, je voulais venir me présenter »"]'::jsonb, 'Les accroches directes annoncent clairement un intérêt amoureux dès le départ.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('478e1b59-9821-4b03-8744-b950a6269270', 'fr', 'Tu vois une femme qui porte une montre vintage. Quelle accroche l’implique ?', '["« Salut, ça va ce soir ? »", "« Tu es jolie. »", "« Tu fais quoi dans la vie ? »", "« Elle a l’air d’avoir une histoire, cette montre. »"]'::jsonb, 'Une supposition précise l’oblige à s’impliquer et à répondre personnellement.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('48e4513c-c89e-4a8b-99e3-d70a28ea7193', 'fr', 'Dans une file d’attente, tu dis : « Tu as l’air bien trop calme pour cette queue. » Elle rit. Qu’est-ce qui marche ?', '["Tu as fait référence à la situation partagée", "Tu as créé un contraste joueur", "Tu as demandé la permission de parler"]'::jsonb, 'Une situation partagée plus une touche de jeu font vite baisser les résistances.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4de13376-2210-4667-8d5f-ae59a38657c2', 'fr', 'Pourquoi clarifier son intérêt par un seul geste direct vaut-il mieux que t’attarder ?', '["Ça raccourcit l’échange", "Ça montre que tu mènes", "Ça évite le rejet", "Ça lui donne de la clarté et le contrôle"]'::jsonb, 'Une phrase claire lève l’ambiguïté et révèle s’il s’agit d’intérêt ou de simple politesse.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4ef57d59-ef61-4420-92a6-2b920652d1b8', 'fr', 'Pourquoi les accroches qui demandent son avis valorisent-elles les gens ?', '["En sollicitant son point de vue, tu dis clairement que son jugement compte", "Demander un avis montre ton intelligence émotionnelle et tes compétences sociales", "Les gens préfèrent parler d’eux qu’écouter"]'::jsonb, 'Les gens s’illuminent quand leur point de vue compte. Se sentir valorisé crée de l’implication.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4fe08740-af66-4896-aa93-6a50f2a41020', 'fr', 'Elle dit « En fait, j’étais sur le point de partir », mais elle s’attarde et continue de te poser des questions.', '["Une façon polie de décrocher", "Un signal mitigé qui penche vers l’ouverture", "Un signal froid adouci par politesse", "Un rejet net"]'::jsonb, 'S’attarder et rester curieuse montre de l’ouverture, malgré les contraintes pratiques.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5027deaf-2157-42e1-b4db-138c9801e876', 'fr', 'Elle sourit, répond positivement, mais dit : « En fait, je révise pour un examen. »', '["Ouverture : sa réponse positive montre de l’intérêt malgré les révisions", "Refus poli : elle est gentille, mais ses révisions posent une limite", "Test : elle veut voir si tu insistes ou si tu respectes ses priorités"]'::jsonb, 'Un ton positif peut être de la politesse ; une priorité annoncée est une limite. Souhaite-lui bonne chance et pars.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('50916cec-9c9c-486c-b266-a45065ff3ea2', 'fr', 'Elle répond avec enthousiasme, pose une question de relance, mais regarde sans arrêt son téléphone.', '["Ouverture : son implication verbale montre un vrai intérêt malgré le téléphone", "Politesse : regarder son téléphone contredit sa chaleur verbale et montre une attention partagée", "Mitigé : ses mots montrent de l’ouverture, mais son comportement suggère de la distraction"]'::jsonb, 'Des signaux mitigés demandent de s’ajuster ; continue brièvement pour voir si son attention revient.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('51786178-0f86-4cb1-b4bd-0b3e68a87f9e', 'fr', 'Pourquoi est-il risqué de prendre la politesse pour de l’intérêt ?', '["Ça ralentit l’échange", "Ça lui met une pression dont elle ne veut pas", "Ça rend l’approche audacieuse"]'::jsonb, 'Son confort passe en premier ; sers-toi des signaux pour décider de continuer ou de lever le pied.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('51944bdf-42d0-42e5-b902-ff0f21714718', 'fr', 'Elle échange chaleureusement, rit, pose des questions, mais dit : « En fait, j’ai un copain. »', '["Ouverture : son implication montre de l’intérêt, parler de son copain est un test", "Politesse : son échange chaleureux était de la gentillesse, son copain est une limite claire", "Mitigé : elle montre de l’intérêt, mais sa situation amoureuse crée un conflit"]'::jsonb, 'Elle était aimable, pas ouverte à une relation ; parler de son copain est une limite claire.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('51f130a3-2032-4c6f-b654-83d546e7b8aa', 'fr', 'Soirée. Elle est polie, mais tu n’es pas sûr de son intérêt. Quelles phrases aident ?', '["« Je vais me chercher un verre. Tu viens ? »", "« Elle est un peu ennuyeuse, cette soirée. »", "« Je te laisse profiter de la soirée. »", "« Viens, je te présente mes amis. »"]'::jsonb, 'Une proposition claire vérifie si elle a envie de bouger, de te rejoindre ou de continuer, sans pression.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('520ac978-94f9-404d-aabe-55099eebb89e', 'fr', 'Elle mentionne qu’elle a étudié à l’étranger. Quelle réponse évite d’avoir un objectif en tête ?', '["Lui demander avec intérêt ce qu’elle a le plus aimé là-bas", "Complimenter son physique pour créer de l’attirance", "Insister vite pour avoir son numéro", "Ne parler que de tes réussites"]'::jsonb, 'Un intérêt sincère pour son histoire lui donne le sentiment d’être vue, pas poursuivie.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('530f7582-4d63-4e0c-bede-bf88b8fdbd71', 'fr', 'Pourquoi dire « Je ne peux rester qu’un instant » aide-t-il à réduire la pression ?', '["Elle sait qu’elle n’est pas coincée dans une conversation sans fin avec un inconnu", "Ça montre que tu respectes son temps et que tu ne vas pas le lui faire perdre", "Le temps limité crée de l’urgence"]'::jsonb, 'Une limite de temps indique que tu vas bientôt partir, ce qui lui fait baisser la garde.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('55289809-9c93-4056-aed5-077280b1ae2f', 'fr', 'Quelle est la principale force des accroches directes ?', '["Elles te donnent plus d’assurance pendant l’approche", "Elles augmentent l’attirance par l’audace", "Elles lèvent l’ambiguïté en annonçant ton intention tout de suite"]'::jsonb, 'Être direct évite les devinettes et va droit à l’intention.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5645caed-20b5-412a-abcf-de263b1e3c46', 'fr', 'Elle fait défiler son téléphone. Que doit faire ton accroche pour marcher ?', '["Être polie", "Être plus forte", "Être intéressante", "Être rapide et percutante"]'::jsonb, 'Ton accroche doit être plus intéressante que ce qu’elle faisait avant.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('59132ed6-d432-4176-9308-5f83ffeb2e2c', 'fr', 'Pourquoi les sourires induisent-ils souvent les hommes en erreur quand ils abordent ?', '["Un sourire signale toujours de l’attirance", "Un sourire est une politesse sociale par défaut", "Les hommes croient que la chaleur veut dire intérêt", "Les deux : un sourire est souvent de la politesse, et les hommes prennent la chaleur pour de l’intérêt"]'::jsonb, 'Un sourire est souvent de la politesse, et les hommes prennent fréquemment la chaleur pour de l’attirance.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5a89ed7d-2ccb-4fb2-ad5a-c8b0d73aab44', 'fr', 'Elle répond poliment mais brièvement à ton accroche. Qu’est-ce qui te permet de continuer à donner le ton ?', '["Poser une autre question intéressante pour avancer", "T’excuser de l’avoir interrompue et partir", "Attendre qu’elle te pose des questions", "T’aligner sur son énergie basse et rester neutre"]'::jsonb, 'C’est toi qui décides de la direction ; continue de mener au lieu de suivre son repli.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5b1abc4a-c6ad-4dd2-b4a0-e8c4cf55f119', 'fr', 'Pourquoi le cerveau lit-il les mouvements du corps avant les mots ?', '["Il traite d’abord le contenu verbal", "Le mouvement signale instinctivement l’intention et la sécurité", "Un mouvement fluide indique l’aisance", "Un mouvement crispé trahit l’anxiété"]'::jsonb, 'Un mouvement détendu transmet la sécurité et lui rend l’échange plus facile.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5b40af44-7fc8-4e4e-93fe-427ce1753d12', 'fr', 'Dans un bar, tu engages la conversation. Elle se tourne à peine, lâche un « salut » plat et balaie la salle du regard pendant que tu parles.', '["Politesse : elle est polie, sans plus ; fais court ou pars", "Froideur : un désintérêt clair ; retire-toi immédiatement", "Test : elle veut voir si tu gardes ta posture malgré son énergie basse"]'::jsonb, 'Un langage corporel fermé pèse plus que les réponses ; recule et pars calmement.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5bd1ec51-0293-467c-b328-37d4c947a52a', 'fr', 'Vous faites tous les deux la queue au café, et elle est longue. Quelles accroches indirectes peux-tu utiliser ?', '["Lui demander ce qu’elle prend d’habitude ici", "Complimenter son sourire", "Faire une remarque sur la lenteur de la file", "Te présenter tout de suite"]'::jsonb, 'Une situation partagée crée une entrée en matière naturelle et sans pression.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5c6d17f6-baa9-4899-916b-fc9639e67f2c', 'fr', 'Elle tient un téléphone avec une coque très originale. Que pourrais-tu dire en premier pour éveiller sa curiosité ?', '["« Tu l’as trouvée où, cette coque ? »", "« Il te plaît, ton téléphone ? »", "« Elle est intéressante, ta coque. »", "« J’ai une question à propos de cette coque. »"]'::jsonb, 'La mise en place crée de la curiosité avant de révéler la question.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5e1e4ba0-77d1-47d1-b948-830f42c9bfc1', 'fr', 'Que se passe-t-il quand tu parles de façon précipitée pendant un échange ?', '["Tu es moins clair", "Ça trahit de la tension", "Ça casse le rythme", "Toutes les réponses ci-dessus"]'::jsonb, 'Quand les mots se bousculent, la clarté baisse et la nervosité se voit. Ralentis.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5e77a13d-51fd-4fc8-8b20-e153be35f50a', 'fr', 'Qu’indique généralement une réponse polie ?', '["Elle est intéressée, mais teste ton assurance et ta posture", "Elle est gentille pour éviter un conflit, malgré un intérêt nul", "Elle hésite ou n’est pas vraiment ouverte ; avance doucement ou pars"]'::jsonb, 'Poli veut dire hésitant ou fermé. Lis attentivement ses signaux suivants.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5f79a125-3233-4761-a27a-0c3df5b785b6', 'fr', 'Que se passe-t-il quand tu annonces une limite de temps ?', '["La pression baisse, parce que l’échange a une sortie prévue", "Elle se détend en sachant que ça ne va pas durer longtemps", "Tu crées une urgence qui lui fait accorder plus de valeur à l’échange"]'::jsonb, 'Une limite enlève la peur d’être coincée, ce qui la met plus à l’aise.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('60bdd118-0868-4732-a177-bad97e1d37de', 'fr', 'Elle a un petit tatouage visible sur le poignet. Que pourrais-tu dire en premier pour éveiller sa curiosité ?', '["« Il est cool, ton tatouage. C’est quoi ? »", "« Il est joli, ce tatouage. »", "« Il faut que je te pose une question sur ce tatouage. »", "« Tu en as d’autres, des tatouages ? »"]'::jsonb, 'La mise en place crée de la curiosité avant de révéler la question.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('610a475a-54e4-4882-b442-6ebc0faac3a8', 'fr', 'Vous faites tous les deux la queue au café, et elle est longue. Quelle accroche indirecte marche le mieux ?', '["« Tu es vraiment jolie, il fallait que je te dise bonjour. »", "« C’est quoi, ton numéro ? »", "« Cette queue, c’est n’importe quoi aujourd’hui, non ? »", "« Tu as l’air d’avoir besoin d’un café. »"]'::jsonb, 'Une remarque sur la situation paraît naturelle et réduit la pression.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('611e32cc-c038-42d3-a1ce-086d78cbcd68', 'fr', 'Elle répond brièvement, détourne le regard et change d’appui. Meilleure réaction ?', '["Poser des questions plus profondes", "La taquiner un peu", "Partir proprement", "Monter en énergie"]'::jsonb, 'Des signes polis de désintérêt veulent dire qu’il est temps de partir ; pars proprement, sans insister.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('61e8562c-6ad4-4305-bf8f-d44fe44652ab', 'fr', 'Quel est le changement d’état d’esprit de fond pour aborder avec curiosité ?', '["« Est-ce que je peux en tirer quelque chose ? »", "« Est-ce que cette personne m’intéresse ? »", "« Comment l’impressionner vite ? »", "« Est-ce que ça va mener à un rendez-vous ? »"]'::jsonb, 'S’intéresser à son monde enlève l’objectif et permet un échange sincère.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6212b078-0050-447a-bf0f-ff2070f3f00c', 'fr', 'File d’attente au café. Tu engages la conversation. Elle sourit brièvement, dit « ouais », puis regarde son téléphone.', '["Neutre : elle est distraite, mais elle pourrait s’impliquer si tu insistes", "Politesse : elle t’a répondu, puis a aussitôt détourné son attention", "Froideur : regarder son téléphone est un signe délibéré de rejet"]'::jsonb, 'Elle t’a répondu, puis a posé une limite ; retire-toi sans prolonger.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('624f3918-37e1-4cec-8932-2afa6e870e81', 'fr', 'Vous êtes tous les deux bloqués à un arrêt de bus sous la pluie. Quelle accroche réduit la pression ?', '["« Tu es magnifique, même sous la pluie. »", "« Tu veux mon numéro ? »", "« Je peux me mettre sous ton parapluie ? »", "« Quel temps pourri. Tu sais si le bus est encore en retard ? »"]'::jsonb, 'Une expérience partagée sur le moment lance la conversation naturellement.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('645565d5-3468-40e0-a262-b135680333a7', 'fr', 'Tu repères sur son sac un porte-clés d’un festival peu connu. Quelle accroche montre de la curiosité ?', '["« Il est cool, ton porte-clés. »", "« Il a de la personnalité, ton sac. »", "« Tu vas à des événements ? »", "« Tu es allée à ce festival ? Il paraît que c’est dingue. »"]'::jsonb, 'Être curieux de ce qu’elle vit invite un vrai lien, sans arrière-pensée.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('66e6b51f-4377-41cc-af99-be7fc8703380', 'fr', 'En journée, à la salle de sport. Elle est entre deux séries. Meilleure chose à faire ?', '["Attendre qu’elle ait complètement fini sa séance pour l’aborder", "Entrer dans son champ de vision, croiser son regard, sourire, l’aborder pendant sa récupération", "Lui demander de t’assurer ou de vérifier ta technique pour créer une ouverture naturelle", "La salle n’est pas un endroit approprié, laisse tomber"]'::jsonb, 'Entre deux séries, la fenêtre est courte ; arrive de façon visible et croise son regard pour éviter l’effet de surprise.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6854fe8c-37a2-4b05-abb5-8e28e81f85df', 'fr', 'Dans la rue. Elle est polie, mais tu n’es pas sûr. Quelles phrases aident à clarifier son niveau d’intérêt ?', '["« Je vais de ce côté de toute façon. Tu m’accompagnes ? »", "« Et tu vas où, comme ça ? »", "« Ça te dirait qu’on prenne un café un de ces jours ? »", "« Tu as l’air intéressante. »"]'::jsonb, 'Une invitation à bouger ou à se revoir teste l’intérêt par l’action, pas par les compliments.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6ae58be8-fa28-4df9-982d-734c8bf6bc6b', 'fr', 'Le moment passe, et tu ressens aussitôt un regret. Qu’est-ce qui l’a causé ?', '["Un refus après avoir essayé", "Son manque d’intérêt", "Une conversation qui n’a mené nulle part", "Le fait d’avoir laissé passer l’occasion sans agir"]'::jsonb, 'Le regret vient des occasions manquées, pas des tentatives ratées.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6c9441f0-7531-4148-a292-db648381ccf0', 'fr', 'Dans une librairie, que pourrais-tu dire pour engager la conversation en demandant son avis ?', '["« J’ai besoin de ton avis : est-ce qu’un livre, c’est un bon cadeau ? »", "« Tu sais où est le rayon romans ? »", "« Excuse-moi, tu lis quelque chose d’intéressant ? »"]'::jsonb, 'Lui dire que tu as besoin de son jugement la valorise tout de suite.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6d84a13d-95e6-437d-9368-891c4d42990a', 'fr', 'Quels signes indiquent généralement de l’ouverture ?', '["Elle te pose des questions en retour", "Elle est tournée vers toi", "Elle répond à tes questions", "Une posture détendue"]'::jsonb, 'Les questions en retour et l’orientation du corps montrent l’intérêt ; considère-les comme des feux verts pour continuer.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6e852fdc-853b-47ca-bd28-81f1c157b93e', 'fr', 'Dans quels lieux les accroches directes marchent-elles le mieux ?', '["Les bars, les boîtes, les soirées et les événements sociaux", "Les bibliothèques calmes ou les bureaux", "Les supermarchés à l’heure de pointe", "Les transports en commun"]'::jsonb, 'Une intention amoureuse paraît normale dans les cadres sociaux où l’on s’attend à faire des rencontres.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6ead40bd-0dee-4b4c-935e-8cf034256a37', 'fr', 'En boîte, tu dis : « Tu as attiré mon regard. » Elle sourit, dit merci, mais se retourne vers ses amies.', '["Lui taper sur l’épaule et essayer de continuer la conversation", "Te présenter à ses amies pour rester dans l’échange", "Partir proprement : un merci sans implication est un refus poli"]'::jsonb, 'Sourire puis se retourner, c’est un refus poli. Rester après ça montre que tu ne sais pas t’ajuster.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('702ce88e-2efa-49c5-9ee5-e08ed426d983', 'fr', 'Qu’est-ce qui rend efficaces les accroches qui éveillent la curiosité ?', '["Elles sollicitent son avis ou son point de vue, pas seulement des faits", "Elles sont plus intéressantes que des questions factuelles prévisibles", "Elles portent sur des sujets sur lesquels elle a naturellement un avis", "Toutes les réponses ci-dessus"]'::jsonb, 'Quand une information est incomplète, le cerveau cherche à la compléter ; sers-t’en pour capter son attention.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('722e2188-0d60-460b-8ec7-ca6850661d5a', 'fr', 'Tu la vois avec une coque de téléphone colorée, peinte à la main. Quelle accroche l’implique ?', '["« Elle est cool, ta coque. »", "« Tu as du style. »", "« Il est quelle heure ? »", "« On dirait que tu as fait cette coque toi-même. »"]'::jsonb, 'Une supposition précise l’oblige à s’impliquer et à répondre personnellement.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('727d61fb-ef06-4574-b2e1-63fb70f840c8', 'fr', 'Quel est le but principal d’une bonne entrée en matière ?', '["Impressionner", "Supprimer le risque de refus", "Susciter l’intérêt", "Éviter le silence"]'::jsonb, 'Une entrée en matière doit éveiller la curiosité et créer une implication émotionnelle.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('732636f6-4948-4cf7-ab3c-1529a104b4c8', 'fr', 'Quelles réactions veulent généralement dire qu’il est temps de partir ?', '["Des réponses en un mot", "Elle se détourne", "Aucune question en retour", "Elle répond à tes questions"]'::jsonb, 'Plusieurs signes de désintérêt signalent qu’il faut partir.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('75d003ed-f14a-4b05-a68f-d5a813844935', 'fr', 'Après ton accroche, elle se met à partager son avis avec enthousiasme. Et ensuite ?', '["Lui demander tout de suite son numéro", "Lui donner d’abord ton propre avis", "Changer vite de sujet", "L’écouter et réagir à son point de vue"]'::jsonb, 'Rebondir sur sa réponse récompense son effort et garde l’élan.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('761e81ae-f2b8-48ba-a7a0-a8ebe688a7e5', 'fr', 'Dans la rue, tu fais une remarque. Elle ralentit, sourit et marche à côté de toi.', '["Elle se sent obligée de te répondre", "Elle est ouverte et choisit de rester dans l’échange", "Elle est neutre et attend que tu aies fini"]'::jsonb, 'Adapter son pas au tien montre une implication volontaire ; continue.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('77d7bb74-c3e1-4044-bfb0-c36b1415c65e', 'fr', 'Pourquoi respecter ses signaux même quand tu ne sais pas si elle est polie ou ouverte ?', '["Mieux vaut partir sur des signaux polis que passer outre des signaux froids", "Respecter l’incertitude montre que tu sais t’ajuster", "Son confort compte plus que ton besoin de « t’assurer » qu’elle est intéressée", "Toutes les réponses ci-dessus"]'::jsonb, 'Dans le doute, respecte le signal le moins intéressé ; son confort passe en premier.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('78cf663a-b29b-480e-a8ef-fe1997c76016', 'fr', 'Tu t’approches et tu dis : « Ça vous dérange si je me joins à vous ? » Ils disent oui, mais continuent leur conversation.', '["Attendre une pause dans leur conversation, puis te présenter", "Faire une blague pour ramener leur attention sur toi", "Partir : tu as demandé à entrer dans leur cadre au lieu de créer le tien"]'::jsonb, 'Quand tu demandes à te joindre à eux, tu entres dans leur réalité ; crée la tienne en arrivant avec quelque chose à dire.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7b6ea2f2-5183-4215-9488-2a520d528b32', 'fr', 'Qu’apporte un regard calme et amical avant de parler ?', '["Il crée une attirance intense immédiate", "Il l’oblige à répondre vite", "Il signale une intention positive sans un mot", "Il cache complètement ton approche"]'::jsonb, 'Un regard chaleureux et amical rassure son système nerveux.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7b879d11-d60e-408e-b0dd-18f2dc6a1bab', 'fr', 'Vous attendez tous les deux un vol en retard à l’aéroport. Quelle accroche réduit la pression ?', '["« Tu as l’air stressée, on discute ? »", "« Je peux avoir ton numéro, pour passer le temps ? »", "« Tu es attirante, même avec ce retard. »", "« Il est pénible, ce retard. Tu sais combien de temps ça va durer ? »"]'::jsonb, 'Une expérience partagée sur le moment lance la conversation naturellement.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7d344225-54cf-45ff-b8bc-1f401a89453f', 'fr', 'Que transmet un mouvement détendu ?', '["Tu penses être à ta place là où tu es", "Ton corps n’affiche ni tension ni malaise", "Tu t’es déjà entraîné à cette situation précise"]'::jsonb, 'Un mouvement fluide signale l’aisance et le fait d’être à ta place.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7e53f4ec-68aa-4155-b6ff-8c9214acf8e2', 'fr', 'Quelle est la principale faiblesse des accroches directes ?', '["Elles ne marchent que dans certains cadres sociaux", "Elles demandent plus d’aisance verbale que les accroches indirectes", "Si tu ne lui plais pas tout de suite, l’échange s’arrête vite"]'::jsonb, 'Une accroche directe l’oblige à te juger tout de suite. Il n’y a pas de complicité pour amortir.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('80d3365a-d883-4997-8988-b8010451c01d', 'fr', 'Tu t’approches, mais elle recule aussitôt. Cause la plus probable ?', '["Tu t’es trop approché ou tu as bloqué ses mouvements", "Elle n’est pas intéressée et crée volontairement de la distance", "Elle doit aller quelque part"]'::jsonb, 'Reculer est un réflexe de sécurité, pas un jugement délibéré.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('81df7422-a32e-4d7e-9ee5-03e32f5773ef', 'fr', 'Quel mécanisme psychologique rend efficaces les accroches par supposition ?', '["Elles la rendent curieuse de savoir comment tu t’es fait cette idée", "Elles flattent son ego", "Elles réduisent le risque de refus"]'::jsonb, 'Une supposition la rend curieuse de ta perception, ce qui la garde mentalement impliquée.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('862f73dc-ec2a-4136-a805-782b65c7eece', 'fr', 'À quoi une seule conversation peut-elle mener ?', '["À des amitiés, des relations ou des occasions inattendues", "À des expériences et des histoires dont tu te souviendras des années", "À rencontrer quelqu’un qui deviendra important dans ta vie", "Toutes les réponses ci-dessus"]'::jsonb, 'Une conversation peut ouvrir des possibilités qui vont bien au-delà du moment.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('884ee9cb-5bc8-4593-8032-1bb68fe20856', 'fr', 'Vous êtes tous les deux à un concert. Quelle est une accroche indirecte ?', '["Lui demander si elle a déjà vu ce groupe ou cet artiste", "Faire une remarque sur la foule ou la salle", "Lui dire qu’elle a des goûts musicaux géniaux"]'::jsonb, 'Rester sur l’expérience partagée laisse l’aisance s’installer naturellement.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('88ec90e6-280c-40aa-896c-018951f9446c', 'fr', 'Elle lit un livre dont tu reconnais la couverture. Quelle accroche montre de la curiosité ?', '["« Tu as l’air de lire beaucoup. »", "« C’est la nouvelle édition ? Tu en penses quoi pour l’instant ? »", "« Bon choix, tu as l’air intelligente. »", "« Ça te dérange si je m’assois avec toi ? »"]'::jsonb, 'Être curieux de ce qu’elle vit invite un vrai lien, sans arrière-pensée.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
commit;
